getInlayHintsForLine(line) {
        if (!this.o.hasModel()) {
            return [];
        }
        const set = new Set();
        const result = [];
        for (const deco of this.o.getLineDecorations(line)) {
            const data = this.j.get(deco.id);
            if (data && !set.has(data.item.hint)) {
                set.add(data.item.hint);
                result.push(data.item);
            }
        }
        return result;
    }
